128	     * @param newPlants the newly generated plants.
129	     */
130	    protected void multiply(double spreadProbability, List<Actor> newPlants)
131	    {
132	        List<Location> freeLocs = field.getFreeAdjacentTerrain(location);
133	        for ( Location loc : freeLocs) {
134	            if(rand.nextDouble() < spreadProbability) {
135	                Plant plant = getSpecies().createYoung(field, loc);
136	                newPlants.add(plant);
137	            }
138	        }
139	    }
