  5	/**
  6	 * A simple predator-prey simulator, based on a rectangular field
  7	 * containing rabbits and foxes.
  8	 *
  9	 * @version 2.0
 10	 */
 11	public class Simulator
 12	{
 13	    
 14	    /*///////////////////////////////////////////////////////////////
 15	                                 CONSTANTS
 16	    //////////////////////////////////////////////////////////////*/
 17	    
 18	    // The default dimensions
 19	    private static final int DEFAULT_WIDTH = 120;
 20	    private static final int DEFAULT_DEPTH = 80;
 21	    
 22	    /*///////////////////////////////////////////////////////////////
 23	                                   STATE
 24	    //////////////////////////////////////////////////////////////*/
 25	    
 26	    // List of animals in the field.
 27	    private List<Actor> animals;
 28	    private List<Actor> plants;
 29	    // The current state of the field.
 30	    private Field field;
 31	    
 32	    private SimulatorClock clock;
 33	    private WeatherHandler weatherHandler;
 34	    // The current step of the simulation.
 35	    private int step;
 36	    // A graphical view of the simulation.
 37	    private SimulatorView view;
 38	    // handles the simulation of the disease
 39	    private DiseaseHandler diseaseHandler;
 40	    // swing component dashboard
 41	    private Dashboard dashboard;
 42	    // generator for the initial terrain and population
 43	    private PopulationGenerator populationGenerator;
 44	    
 45	    /*///////////////////////////////////////////////////////////////
 46	                                CONSTRUCTORS
 47	    //////////////////////////////////////////////////////////////*/
 48	    
 49	    /**
 50	     * Construct a simulation field with default size.
 51	     */
 52	    public Simulator() throws Exception
 53	    {
 54	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
 55	    }
 56	    
 57	    /**
 58	     * Create a simulation field with the given size.
 59	     * 
 60	     * @param depth Depth of the field. Must be greater than zero.
 61	     * @param width Width of the field. Must be greater than zero.
 62	     */
 63	    public Simulator(int depth, int width) throws Exception
 64	    {
 65	        if(depth % 20 != 0 || width % 20 != 0) {
 66	            throw new Exception("Depth and Width must be factors of 20");
 67	        }
 68	        
 69	        if(width <= 0 || depth <= 0) {
 70	            depth = DEFAULT_DEPTH;
 71	            width = DEFAULT_WIDTH;
 72	        }
 73	        
 74	        animals = new ArrayList<>();
 75	        plants = new ArrayList<>();
 76	        field = new Field(depth, width);
 77	        clock = new SimulatorClock();
 78	        weatherHandler = new WeatherHandler(clock);
 79	        diseaseHandler = new DiseaseHandler( field);
 80	        // Create a view of the state of each location in the field.
 81	        view = new SimulatorView(depth, width, this);
 82	        populationGenerator = new PopulationGenerator(view, field);
 83	        
 84	        reset();
 85	    }
 86	    
 87	    /**
 88	     * Sets the dashboard field to later updates the interface at the end of simulation steps.
 89	     * 
 90	     * @param newDashboard the dashboard to be updated.
 91	     */
 92	    public void setDashboard(Dashboard newDashboard) {
 93	        this.dashboard = newDashboard;
 94	    }
 95	    
 96	    /*///////////////////////////////////////////////////////////////
 97	                          ECOSYSTEM SIMULATION LOGIC
 98	    //////////////////////////////////////////////////////////////*/
 99	    
100	    /**
101	     * Run the simulation from its current state for a reasonably long period,
102	     * (1000 steps).
103	     */
104	    public void runLongSimulation()
105	    {
106	        simulate(1000);
107	    }
108	    
109	    /**
110	     * Run the simulation from its current state for the given number of steps.
111	     * Stop before the given number of steps if it ceases to be viable.
112	     * 
113	     * @param numSteps The number of steps to run for.
114	     */
115	    public void simulate(int numSteps)
116	    {
117	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
118	            simulateOneStep();
119	            //delay(1000);   // uncomment this to run more slowly
120	        }
121	    }
122	    
123	    /**
124	     * Run the simulation from its current state for a single step.
125	     * Iterate over the whole field updating the state of each
126	     * fox and rabbit.
127	     */
128	    public void simulateOneStep()
129	    {
130	        step++;
131	        clock.incrementStep();
132	        weatherHandler.updateWeather();
133	        diseaseHandler.simulateDiseaseStep();
134	        
135	        List<Actor> newAnimals = new ArrayList<>();
136	        List<Actor> newPlants = new ArrayList<>();
137	        
138	        actorsAct(plants, newPlants);
139	        actorsAct(animals, newAnimals);        
140	        
141	        view.showStatus(step, field, clock, weatherHandler.getWeather());
142	
143	        if(dashboard != null) {
144	            dashboard.updateDashboard();            
145	        }
146	    }
147	        
148	    /**
149	     * Reset the simulation to a starting position.
150	     */
151	    public void reset()
152	    {
153	        step = 0;
154	        clock.reset();
155	        weatherHandler.reset();
156	        diseaseHandler.reset();
157	        animals.clear();
158	        plants.clear();
159	        populationGenerator.populate(animals, plants);
160	        
161	        // Show the starting state in the view.
162	        view.showStatus(step, field, clock, weatherHandler.getWeather());
163	    }
164	
165	    /**
166	     * Returns the tracked disease history.
167	     */
168	    public NavigableMap<Integer, Integer> getDiseaseHistory()
169	    {
170	        return diseaseHandler.getInfectionCounts();
171	    }
172	    
173	    /**
174	     * Iterates through a set of actors and makes them act, die if they are dead and subsequently adds the newborns.
175	     * 
176	     * @param actors List of all actors in the field.
177	     * @param newActors List of newborns after actors act.
178	     */
179	    private void actorsAct(List<Actor> actors, List<Actor> newActors) {
180	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
181	            Actor actor = it.next();
182	            actor.act(newActors, weatherHandler.getWeather(), clock.getDayState());
183	            if(! actor.isAlive()) {
184	                it.remove();
185	            }
186	        }
187	        actors.addAll(newActors);
188	    }
189	    
190	    /**
191	     * Pause for a given time.
192	     * 
193	     * @param millisec The time to pause for, in milliseconds.
194	     */
195	    private void delay(int millisec)
196	    {
197	        try {
198	            Thread.sleep(millisec);
199	        }
200	        catch (InterruptedException ie) {
201	        }
202	    }
203	}

