  3	/**
  4	 * An extension of the Animal Class that can only eat a specified type of animals
  5	 *
  6	 * @version 1.0
  7	 */
  8	public abstract class CarnivoreAnimal extends Animal
  9	{
 10	    
 11	    /*///////////////////////////////////////////////////////////////
 12	                                CONSTRUCTOR
 13	    //////////////////////////////////////////////////////////////*/
 14	    
 15	    /**
 16	     * Creates a Carnivore Animal.
 17	     * 
 18	     * @param randomAge Boolean flag dictating whether or not the attributes will be assigned a random value
 19	     * @param field The environment the animal can move in
 20	     * @param location Location of the animal in the field/grid
 21	     * @param gender Gender of the animal
 22	     * @param baseLevel the base hunger index associated with the animal
 23	     * @param maxAge the maximum age an animal can take before he dies.
 24	     */
 25	    
 26	    public CarnivoreAnimal(boolean randomAge,
 27	                            Field field,
 28	                            Location location,
 29	                            Gender gender,
 30	                            int baseLevel,
 31	                            int maxLevel
 32	                            )
 33	    {
 34	        super(randomAge,field, location, gender, baseLevel, maxLevel);
 35	    }
 36	
 37	    protected abstract int getMaxAge();
 38	
 39	    protected abstract int getBreedingAge();
 40	
 41	    protected abstract double getBreedingProbability(Weather weather);
 42	
 43	    protected abstract int getMaxLitterSize();
 44	
 45	    protected abstract List<Class<? extends Animal>> getPreyDiet();
 46	
 47	    protected boolean canAct(Weather weather, DayState dayState)
 48	    {
 49	        return true;
 50	    }
 51	
 52	    protected void onFoodFound(Location location)
 53	    {
 54	    }
 55	
 56	    @Override
 57	    public final void act(List<Actor> newAnimals, Weather weather, DayState dayState)
 58	    {
 59	        if(!canAct(weather, dayState)) {
 60	            return;
 61	        }
 62	        incrementAge(getMaxAge());
 63	        incrementHunger();
 64	        if(!isAlive()) {
 65	            return;
 66	        }
 67	        meet(newAnimals, getMaxLitterSize(), getBreedingProbability(weather), getBreedingAge());
 68	        Location newLocation = findFood(getPreyDiet());
 69	        if(newLocation != null) {
 70	            onFoodFound(newLocation);
 71	        }
 72	        if(newLocation == null) {
 73	            newLocation = getField().freeAdjacentLocation(getLocation());
 74	        }
 75	        if(newLocation != null) {
 76	            setLocation(newLocation);
 77	        }
 78	        else {
 79	            setDead();
 80	        }
 81	    }
 82	    
 83	    /**
 84	     * Seek for the food in adjacent locations that are of type of plant.
 85	     * 
 86	     * @param preys The preys of the animal.
 87	     * @return the location traveled to in order to access the food.
 88	     */
 89	    public Location findFood(List<Class<? extends Animal>> preys)
 90	    {   
 91	        Field field = getField();
 92	        List<Location> adjacent = field.adjacentLocations(getLocation());
 93	        Iterator<Location> it = adjacent.iterator();
 94	        while(it.hasNext()) {
 95	            Location where = it.next();
 96	            Object obj = field.getObjectAt(where);
 97	            if(obj instanceof Animal) {
 98	                Animal animal = (Animal) obj;
 99	                if(preys.contains(animal.getClass())) {
100	                    if(animal.isAlive()) {
101	                        animal.setDead();
102	                        
103	                        this.foodLevel = animal.getFeedingValue();
104	                        return where;
105	                    }
106	                }
107	            }
108	        }
109	        return null; 
110	    }
111	}

