 48	     * 
 49	     * @return the current time.
 50	     */
 51	    public double getTime()
 52	    {
 53	        return (((double)(TIME_FACTOR) * step) + INITIAL_TIME) % 24;
 54	    }
 55	    
 56	    /**
 57	     * Accessor method for the current hour of the day.
 58	     * 
 59	     * @return the current hour (floored).
 60	     */
 61	    public int getHourOfDay()
 62	    {
 63	        return (int) getTime();
 64	    }
 65	    
 66	    /**
 67	     * The remainder of the current hours.
 68	     * 
 69	     * @return the minutes passed since the start of the last hour.
 70	     */
 71	    public int getMinuteOfDay()
 72	    {
 73	        return (int)((getTime() - (double)getHourOfDay()) * 100.0 * 0.6);
 74	    }
 75	    
 76	    /**
 77	     * Increments the internal steps of the clock.
 78	     */
 79	    public void incrementStep()
 80	    {
 81	        step++;
 82	    }
 83	
 84	    /**
 85	     * Resets the clock back to the initial simulation state.
 86	     */
 87	    public void reset()
 88	    {
 89	        step = 0;
 90	    }
 91	    
 92	    /**
 93	     * Returns the number of days passed since the start of the simulation(starts at day 1).
 94	     * 
 95	     * @return the current day of the simulation.
 96	     */
 97	    public int getDayCount()
 98	    {
 99	        return ((int)((step + (INITIAL_TIME/TIME_FACTOR)) / STEPS_PER_DAY) + 1);
100	    }
101	    
102	    /**
103	     * Returns the current state of the day.
104	     * 
105	     * @returns the state of the day.
106	     */
107	    public DayState getDayState()
108	    {
109	        if(getTime() > 24 || getTime() < 6) {
110	            return DayState.NIGHT;
111	        } else {
112	            return DayState.DAYLIGHT;
113	        }
114	    }
115	}

 1	import java.util.List;
 2	import java.util.Iterator;
 3	/**
 4	 * An extension of the Animal Class that can only eat a specified type of plants
 5	 *
 6	 * @version 1.0
 7	 */
 8	public abstract class HerbivoreAnimal extends Animal
 9	{
10	    
11	    /*///////////////////////////////////////////////////////////////
12	                                CONSTRUCTOR
13	    //////////////////////////////////////////////////////////////*/
14	
15	    /**
16	     * Creates a Herbivore Animal.
17	     * 
18	     * @param randomAge Boolean flag dictating whether or not the attributes will be assigned a random value
19	     * @param field The environment the animal can move in
20	     * @param location Location of the animal in the field/grid
21	     * @param gender Gender of the animal
22	     * @param baseLevel the base hunger index associated with the animal
23	     * @param maxAge the maximum age an animal can take before he dies.
24	     */
25	    
26	    public HerbivoreAnimal(boolean randomAge,Field field, Location location, Gender gender, int baseLevel, int maxAge)
27	    {
28	        super(randomAge, field, location, gender, baseLevel, maxAge);
29	    }
30	
31	    protected abstract int getMaxAge();
32	
33	    protected abstract int getBreedingAge();
34	
35	    protected abstract double getBreedingProbability(Weather weather);
36	
37	    protected abstract int getMaxLitterSize();
38	
39	    protected abstract List<Class<? extends Plant>> getTargetPlants();
40	
41	    @Override
42	    public final void act(List<Actor> newAnimals, Weather weather, DayState dayState)
43	    {
44	        incrementAge(getMaxAge());
45	        incrementHunger();
46	        if(!isAlive()) {
47	            return;
48	        }
49	        meet(newAnimals, getMaxLitterSize(), getBreedingProbability(weather), getBreedingAge());
50	        Location newLocation = findFood(getTargetPlants());
51	        if(newLocation == null) {
52	            newLocation = getField().freeAdjacentLocation(getLocation());
53	        }
54	        if(newLocation != null) {
55	            setLocation(newLocation);
56	        }
57	        else {
58	            setDead();
59	        }
60	    }
61	    
62	    /**
63	     * Seek for the food in adjacent locations that are of type of plant
64	     * @param targetPlants the preferred diet of the animal (e.g eats only grass)
65	     * @return the location traveled to in order to access the food
66	     */
67	    public Location findFood(List<Class<? extends Plant>> targetPlants) 
68	    {
69	        Field field = getField();
70	        List<Location> adjacent = field.adjacentLocations(getLocation());
71	        Iterator<Location> it = adjacent.iterator();
72	        while(it.hasNext()) {
73	            Location where = it.next();
74	            Plant plant = field.getPlantAt(where);
75	            if(plant != null && targetPlants.contains(plant.getClass())) {
76	                if(plant.isAlive()) {
77	                    this.foodLevel += plant.getFeedingValue();
78	                    plant.setDead();
79	                    return where;
80	                }
81	            }
82	        }
83	        return null;
84	    }
85	}
